// seed: tests/seed.spec.ts (гость; сессии .qa/auth — для www, на vercel.app другой origin) · прод, только чтение.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, readSellerMessages, expectSellerMessage, VERCEL } from './whatsapp.helpers';

// Свежий бандл vercel.app, без старого кэша SW.
test.use({ serviceWorkers: 'block' });

test.describe('WhatsApp למוכר — готовое сообщение продавцу', () => {
  for (const path of ['/', '/search']) {
    test(`biz4sale.vercel.app${path}: ссылка в сообщении на www.biz4sale.co.il, не vercel.app #1d84d2 #e8bbad @android @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.goto(VERCEL + path);
      expect(new URL(page.url()).host, 'остались на vercel.app (сценарий клиента)').toBe('biz4sale.vercel.app');
      const messages = await readSellerMessages(page);
      expect(messages.length, 'есть сообщения продавцу').toBeGreaterThan(0);
      for (const m of messages) {
        expect(m.text, 'нет ссылки на vercel.app').not.toContain('vercel.app');
        expectSellerMessage(m, VERCEL + path);
      }
    });
  }
});
